#include "field_qq.hpp"
#include <algorithm>
#include <tuple>
vector<Rat> unitFactors; void loadUnitFactors(const char*path){ifstream in(path);int n;in>>n;unitFactors.resize(n);for(auto&v:unitFactors)readpoly(in,v.n);}
Rat lc(const Rat&v){Rat c;slong var=1;ulong power=fmpq_mpoly_degree_si(v.n,1,ctx);fmpq_mpoly_get_coeff_vars_ui(c.n,v.n,&var,&power,1,ctx);return c;}
void primitive(Row&r){Rat g,t,c;slong var=1;for(auto&[j,v]:r){assert(fmpq_mpoly_content_vars(c.n,v.n,&var,1,ctx));assert(fmpq_mpoly_degree_si(c.n,1,ctx)<=0);assert(fmpq_mpoly_gcd(t.n,g.n,c.n,ctx));fmpq_mpoly_swap(t.n,g.n,ctx);if(fmpq_mpoly_total_degree_si(g.n,ctx)==0)break;}if(g.zero())return;for(auto&[j,v]:r){assert(fmpq_mpoly_divides(t.n,v.n,g.n,ctx));fmpq_mpoly_swap(t.n,v.n,ctx);}bool changed=true;while(changed){changed=false;for(auto&ff:unitFactors){fmpq_mpoly_set(g.n,ff.n,ctx);for(auto&[j,v]:r){assert(fmpq_mpoly_gcd(t.n,g.n,v.n,ctx));fmpq_mpoly_swap(t.n,g.n,ctx);if(fmpq_mpoly_total_degree_si(g.n,ctx)==0)break;}if(fmpq_mpoly_degree_si(g.n,1,ctx)>0){for(auto&[j,v]:r){assert(fmpq_mpoly_divides(t.n,v.n,g.n,ctx));fmpq_mpoly_swap(t.n,v.n,ctx);}changed=true;}}}}
void rowSubtract(Row&b,const Row&a,const Rat&pa,const Rat&pb){Rat tmp,t;for(auto&[j,v]:b){fmpq_mpoly_mul(tmp.n,v.n,pa.n,ctx);fmpq_mpoly_swap(tmp.n,v.n,ctx);}for(auto&[j,v]:a){fmpq_mpoly_mul(tmp.n,pb.n,v.n,ctx);fmpq_mpoly_sub(t.n,b[j].n,tmp.n,ctx);if(t.zero())b.erase(j);else fmpq_mpoly_swap(t.n,b[j].n,ctx);}primitive(b);}
Rat leadCoeff(const Rat&v){Rat c;slong var=1;ulong power=fmpq_mpoly_degree_si(v.n,1,ctx);fmpq_mpoly_get_coeff_vars_ui(c.n,v.n,&var,&power,1,ctx);fmpq_mpoly_set(c.d,v.d,ctx);c.reduce();return c;}
Rat polynomialQuotient(const Rat&a,const Rat&b){int bd=fmpq_mpoly_degree_si(b.n,1,ctx);if(bd==0)return divi(a,b);Rat rem=a,q,lb=leadCoeff(b);while(!rem.zero()&&fmpq_mpoly_degree_si(rem.n,1,ctx)>=bd){int dd=fmpq_mpoly_degree_si(rem.n,1,ctx)-bd;Rat mon,c=divi(leadCoeff(rem),lb);ulong ex[2]={0,ulong(dd)};fmpq_mpoly_gen(mon.n,1,ctx);assert(fmpq_mpoly_pow_ui(mon.n,mon.n,dd,ctx));c=mul(c,mon);Rat neg=c;fmpq_mpoly_neg(neg.n,neg.n,ctx);q=sub(q,neg);rem=sub(rem,mul(c,b));}return q;}
pair<int,int>lead(const Row&r){int degree=-1,col=-1;for(auto&[j,v]:r){int d=fmpq_mpoly_degree_si(v.n,1,ctx);if(d>degree||(d==degree&&j>col)){degree=d;col=j;}}return{degree,col};}
int main(int argc,char**argv){fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{loadUnitFactors(argv[3]);ifstream in(argv[1]);int nr,nc;in>>nr>>nc;vector<Row>A(nr),B(nc);for(auto&row:A){int n;in>>n;Rat den,g,t;fmpq_mpoly_one(den.n,ctx);for(int k=0;k<n;k++){int j;in>>j;Rat x;readpoly(in,x.n);readpoly(in,x.d);assert(fmpq_mpoly_degree_si(x.d,1,ctx)<=0);assert(fmpq_mpoly_gcd(g.n,den.n,x.d,ctx));assert(fmpq_mpoly_divides(t.n,x.d,g.n,ctx));fmpq_mpoly_mul(g.n,den.n,t.n,ctx);fmpq_mpoly_swap(g.n,den.n,ctx);if(!x.zero())row.emplace(j,std::move(x));}for(auto&[j,v]:row){assert(fmpq_mpoly_divides(t.n,den.n,v.d,ctx));fmpq_mpoly_mul(g.n,t.n,v.n,ctx);fmpq_mpoly_swap(g.n,v.n,ctx);fmpq_mpoly_one(v.d,ctx);}primitive(row);}
vector<pair<pair<int,long>,int>> order;for(int i=0;i<nr;i++){long terms=0;for(auto&[j,v]:A[i])terms+=fmpq_mpoly_length(v.n,ctx);order.push_back({{lead(A[i]).first,terms},i});}sort(order.begin(),order.end());int steps=0,rank=0;for(auto[score,i]:order){Row row=std::move(A[i]);while(!row.empty()){auto[d,c]=lead(row);if(B[c].empty()){B[c]=std::move(row);rank++;break;}auto[bd,bc]=lead(B[c]);assert(bc==c);if(d<bd){row.swap(B[c]);swap(d,bd);}Rat q=polynomialQuotient(row[c],B[c][c]),pa,pb;assert(fmpq_mpoly_degree_si(q.d,1,ctx)<=0);fmpq_mpoly_set(pa.n,q.d,ctx);fmpq_mpoly_set(pb.n,q.n,ctx);rowSubtract(row,B[c],pa,pb);auto nd=lead(row);assert(row.empty()||nd.first<d||(nd.first==d&&nd.second<c));if(++steps%50==0)cerr<<"step "<<steps<<" input "<<i<<" rank "<<rank<<" active degree "<<nd.first<<'\n';}int sum=0;for(auto&r:B)if(!r.empty())sum+=lead(r).first;cerr<<"row "<<i<<" rank "<<rank<<" indexdegree "<<sum<<" steps "<<steps<<'\n';}
ofstream out(argv[2]);out<<rank<<' '<<nc<<'\n';for(int c=0;c<nc;c++)if(!B[c].empty()){auto&r=B[c];out<<c<<' '<<r.size()<<'\n';for(auto&[j,v]:r){out<<j<<'\n';writepoly(out,v.n);writepoly(out,v.d);}}unitFactors.clear();}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
